    "quantity": 1,
    "costEb": 1000,
    "notes": "Нужна помощь в повседневных задачах, но вы не готовы ради этого отрезать свою «любимую» руку? Dynalar, производитель самых надежных в мире киберпальцев,предлагает решение именно для вас. Благодаря простому ремешку и разъему совершенно новый набор пальцев в вашем распоряжении. Умная перчатка Xtra-Dex идеально подходит для всех: от хардкорных профессионалов до домохозяек в запаре. Создайте свою собственную смарт-перчатку для своей смарт-жизни, а затем расслабьтесь и позвольте Dynalar сделать все остальное!Dynalar Xtra-Dex Смарт-перчатка содержит 2 Слота Опций Киберруки или Киберконечности и считается Кистью для Модульных Пальцев совместимой с 5 пальцами. Эти Киберпальцы встроены в пальцы перчатки и не добавляют дополнительных пальцев кисти владельца. Когда используется, опции находящие в слотах перчатки и модульные пальцы могут быть доступны для использования пользователем до тех пор пока перчатка подсоединена к пользователю через Личный Порт. Снять и одеть перчатку занимает одно действие , частью которого пользователь может подключить/отключить Личный Порт. Любые опции находящиеся в киберруке или в мясной руке недоступны пока Xtra-Dex Смарт-перчатка одета поверх данной руки. Не может быть скрыта. Для более подробной информации о киберпальцах смотрите “Чёрный Хром”."
