    "costEb": 750,
    "notes": "Будь самой яркой звездой бара с умной перчаткой CyberDude. Настраивай её под себя, как душе угодно. Оцени изящный дизайн от Wyzard Technologies — ладони скользят, будто по воздуху, а прохладный поток играет на каждом пальце. Так как ты киберишь, чувак? Беспалая умная перчатка, в которой уже предустановлен подкожный захват и два дополнительных слота опций — для опций киберруки или киберконечности. Когда ты носишь перчатку, все опции, встроенные в неё, доступны. Надеть или снять умную перчатку — отдельное действие. Цена установки опций киберруки или киберконечности в перчатку такая же, как и при установке в настоящую киберруку. При этом любой киберимплант (кроме тех, что встроены в пальцы), установленный в киберруке или обычной руке, на которую надета перчатка, становится недоступен, пока перчатка надета. Импланты, встроенные в пальцы — такие как киберпальцы, Быстрые Пальцы, Коготки, Потрошители и «Slice N'Dice» — работают как обычно. Спрятать перчатку CyberDude невозможно."
