    "quantity": 1,
    "costEb": 2500,
    "notes": "Звук. Ценой всего остального. Вы справитесь с любым дискомфортом, который встанет между вами и вашим видением. Музыка требует самоотдачи. Мы создали этот топор, чтобы согласиться. Мы отправляем его настоящим рок-звёздам, тем, кто засыпает в студии и просыпается в ванной. Рубай или будешь порублен — альтернативы року нет. Электрогитара, дающая своему владельцу +2 к проверкам навыка игры на музыкальном инструменте (гитаре), но только если базовый уровень навыка игры на музыкальном инструменте пользователя составляет 16 или выше, исключительно на основе СТАТИСТИКИ пользователя и навыка игры на музыкальном инструменте (гитаре). Навык, полученный от чипа навыка, и все остальные бонусы не учитываются при преодолении этого порога. Этот бонус применяется только один раз и не суммируется с другими инструментами, дающими бонусы к навыку игры на музыкальном инструменте. Этот эффект нельзя изменить или усилить с помощью Ролевой способности «Создатель». KillStrom Power Chord не может быть уничтожен или неэстетично поврежден огнём или любым источником урона, наносящим менее 6 кубиков урона за одну атаку. Не-Рокербой, не подходящий под требования для бонуса предмета, получает критический урон «Раздробленные пальцы» (без бонусного урона), если играет на этой гитаре 10 минут или более. Многие владельцы улучшают свой Power Chord, превращая его в Очень Тяжёлое оружие ближнего боя или огнемёт."
