    "magCapacity": 4,
    "currentAmmo": 4,
    "ammoType": "4 Дротик на леске",
    "concealable": true,
    "costEb": 500,
    "notes": "Во время принудительного «поглощения» SlamDance Incorporated корпорацией SovOil, горстке оружей ников удалось сбежать в Японию. Там они продали чертежи этого гарпунного оружия против бронецелей компании Sanroo, в спешке переоформив его в корпус в форме техпечатной кошачьей мордочки. С тех пор беглые СлэмДансеры скрылись из виду, пытаясь избежать гнева генерального директора SovOil, Анатолия Новарагова.\nЭто экзотический тяжёлый пистолет с магазином на 4 выстрела. Стреляет с использованием навыка Стрельба из лука и не может поражать цели дальше 50 м (25 клеток). Fisher Kitty выпускает мини-гарпуны на вольфрамовых тросах, наносящие 2d6 урона. Эти гарпуны не могут вызвать критические травмы. Если атака успешна, мини-гарпун прилипает к цели, даже если не пробил броню и не нанёс урон. Чтобы вынуть гарпун, требуется Действие. Если цель отдаляется на более чем 50 м (25 клеток) от стрелка, оружие автоматически выдёргивает застрявшие гарпуны. При перезарядке все выпущенные гарпуны автоматически втягиваются обратно. Несовместимо с любыми модификациями магазинов. Пользователь может потратить действие, чтобы электризовать оружие, нанеся разряд по любой цели, в которую попали два или более мини-гарпунов. Разряд наносит 2d6 урона по ПЗ цели, либо 3d6, если в ней застряли три и более гарпунов.\n\nПараметры источника: Навык: Пистолет; Урон: 2d6 3d6; Магазин: 4 Дротик на леске; ROF: 2; Руки: 1; Слотов модификации: -; Можно Скрыть: ДА; Цена: 500eb (Дорого)",
