    "notes": "Возьмите трубку из стекловолокна, добавьте несколько гильз и ударно-спусковой механизм, и вы получите OnlyChance. Эти вещи дешевы и рассчитаны на одноразовое использование, так как попытка их перезарядки неизбежно приводит к поломке ударно-спускового механизма. Они выпускаются с различными сортами боеприпасов. Соберите их все!\nДробовик низкого качества. OnlyChance поставляется с предварительно загруженным определенным типом боеприпасов в зависимости от его «сорта» (при покупке выберите жаканы или дробь. Применяя обычные ограничения) и не может быть перезаряжен будучи опустошённым. Попытка извлечь боеприпасы разрушает оружие и боеприпасы внутри, уничтожая и то, и другое без возможности восстановления. OnlyChance не подлежит техническому улучшению, но принимает все совместимые опции, не относящиеся к магазинам, поэтому снимите всё, что вы установили, прежде чем выбрасывать оружие!\n\nПараметры источника: Навык: Тактическое; Урон: 3d6 5d6; Магазин: 4 Дробовик; ROF: 1; Руки: 2; Слотов Модификаций: 3; Можно скрыть: НЕТ; Цена: Базовые и резиновые боеприпасы стоят 20 eb (Обычное). / Бронебойные, экспансивные и зажигательные боеприпасы стоят 50 eb (Дорого).",
