    "costEb": 600,
    "notes": "Войска часто используют дробовики для нанесения максимального урона на близком расстоянии, поэтому компания Mustang Arms добавила к Deathstalker «ядовитое жало», чтобы обеспечить больше разнообразия при выборе способа убийства цели.\nДробовик стандартного качества. Он оснащен установленным штыком-Аэрогипо.\n\nПараметры источника: Навык: Тактическое; Урон: 3d6 5d6; Магазин: 4 Дробовик; ROF: 1; Руки: 2; Слотов Модификаций: 2; Можно скрыть: НЕТ; Цена: 600eb (Дорого)",
