    "notes": "Militech Ronin Light Assault на протяжении десятилетий был стандартом для вооруженных сил США и войск Militech. Возможно, существовало и лучшее оружие, но «Ронин» был прост в использовании и обслуживании, и в военных арсеналах по всему миру были миллионы таких единиц. Даже сегодня Ронин является обычным предметом в арсенале большинства Соло.\nШтурмовая винтовка стандартного качества.\n\nПараметры источника: Навык: Автоогонь, / Тактическое; Урон: 5d6; Магазин: 25 Винтовка; ROF: 1; Руки: 2; Слотов Модификаций: 3; Можно скрыть: НЕТ; Цена: 500eb (Дорого)",
