    "costEb": 1600,
    "notes": "Как и почти все, что производит Sternmeyer, M-95AF демонстрирует приверженность компании точной подгонке. Дизайн кажется тонким и элегантным, несмотря на вес оружия. Большинство M-95AF, представленных сегодня на рынке, попали через мародеров, совершивших набег на объекты IEC после их краха.\nШтурмовая винтовка отличного качества. Поставляется с установленным барабанным магазином и снайперским прицелом.\n\nПараметры источника: Навык: Автоогонь, / Тактическое; Урон: 5d6; Магазин: 45 Винтовка; ROF: 1; Руки: 2; Слотов Модификаций: 1; Можно скрыть: НЕТ; Цена: 1600eb (Очень Дорого)",
