    "notes": "Летальный/нелетальный\nрежим\n\nЭкзотический тяжелый пистолет низкого качества не имеет спускового крючка и поставляется со встроенным модулем Умного Оружия. Он способен подключаться только к Смартлинку, который необходим для его работы. Когда вы стреляете из этого оружия, вы можете выбрать либо смертельный, либо не смертельный вариант.\nСмертельный вариант стреляет так же, как и обычный тяжелый пистолет, а патроны для него берутся из стандартного 8-зарядного магазина. В не смертельном варианте урон наносится как у тяжелого пистолета, но если урон, нанесенный выстрелом, снижает здоровье цели до 1 ПЗ, то вместо этого она теряет сознание на 1 ПЗ. Кроме того, урон, наносимый этим оружием в его не смертельном режиме, не может вызвать критическое ранение и не разрушает броню. При использовании не смертельного режима вместо использования боеприпасов из магазина оружия расходуется один выстрел из стандартного восьмизарядного аккумулятора 50eb (Ценное), перезаряжаемого (1 час). При необходимости, новая батарея может быть установлена в качестве действия.\nИсточник: Черный Хром\n\nПараметры источника: Навык: Пистолет; Урон: 3d6; Магазин: 8 Батарея, / 8 Т Пистолет; ROF: 2; Руки: 1; Можно Скрыть: ДА; Цена: 500eb / (Дорогое)",
    "quality": "Poor",
    "skillId": "handgun",
    "sourceUrl": "https://alec-leon.github.io/data-pool/equipment/weapons/#pistol-exotic"
