    "notes": "Автоогонь(3)\n\nЭкзотический ПП, способный вести только автоогонь, и не способный к Прицельной Атаке или Одиночному выстрелу. Не смотря на то, что является Экзотическим оружием, может использовать любой боеприпас. В отличии от другого оружия, тратит на Автоогонь 6 патронов вместо 10.\nИсточник: Черный Хром\n\nПараметры источника: Навык: Автоогонь; Урон: 2d6; Магазин: 30 С Пистолет; ROF: 1; Руки: 1; Можно Скрыть: НЕТ; Цена: 1000eb / (Оч.Дорогое)",
