    "ammoType": "30 Собственный боеприпас",
    "concealable": false,
    "costEb": 10,
    "notes": "Автоогонь(3)\n\nЭкзотический ПП который стреляет только Автоогнём. Он заряжается только специализированными коробами по 30 патронов, стоимостью 20eb (Повседневно) за короб. После начала стрельбы, оружие продолжает вести Автоогонь, на протяжении ещё двух ходов пользователя, даже если его уронить, бросить или в случае безвременной кончины хозяина. На протяжении этих двух ходов пользователь тратит Действие чтобы контролировать Автоогонь, в противном случае, считается, что оружие имеет навык Автоогня 10, и цель выбирается Рефери. Из-за размеров оружие не является скрытным.\nИсточник: Черный Хром+\n\nПараметры источника: Навык: Автоогонь; Урон: 2d6; Магазин: 30 Собственный боеприпас; ROF: 1; Руки: 1; Можно Скрыть: НЕТ; Цена: 10eb / (Дешёвка)",
