    "concealable": false,
    "costEb": 1000,
    "notes": "Взрывы,\nДробь 3d6,\nЖакан 5d6,\nУмнаяРакета\n\nЭто либо экзотический дробовик, либо экзотическая ракетница, в зависимости от того, какими боеприпасами он заряжен. Его уникальный магазин с нижней подачей может вмещать либо 4 обычных пули/дробовых патрона дробовика, либо 2 Умные Ракеты. Других видов ракетных боеприпасов не поддерживает. Для стрельбы из него используется навык Тактическое Оружие, когда он работает как дробовик, и навык Оружие Крупного калибра, когда стреляет Умными Ракетами. Лазерная система прицеливания позволяет оружию стрелять Умными Ракетами без использования импланта Тактический Прицел.\nИсточник: Черный Хром\n\nПараметры источника: Навык: Ор.кр.калибра / Тактическое; Урон: 3d6 / 5d6 / 8d6; Магазин: 4 Дробовик, / 2 Ракета; ROF: 1; Руки: 2; Можно Скрыть: НЕТ; Цена: 1000eb / (Оч.Дорогое)",
