    "costEb": 1000,
    "notes": "Дробь 3d6,\nЖакан 5d6,\nЛюбой боеприпас,\nТЕЛ 10+ или установка без получения травмы \"Сломанная рука\"\"\n\nЭРРАТОЙ УБРАН ТЕГ ЭКЗОТИЧЕСКОЕ\nДробовик с 40 патронами в магазине. Имеет всего 2 слота опций снаряжения, и несовместим со всеми модификациями магазина. Для стрельбы из этого оружия без получения критической травмы \"\"Сломанная рука\"\" требуется ТЕЛ 10 или выше, если только оружие не закреплено.\nПерезарядка этого оружия требует использования 2 Действий, и поэтому может быть выполнена только в течение 2 Ходов.\nИсточник: Черный Хром\n\nПараметры источника: Навык: Тактическое; Урон: 3d6 / 5d6; Магазин: 40 Дробовик; ROF: 1; Руки: 2; Можно Скрыть: НЕТ; Цена: 1000eb / (Оч.Дорогое)",
