    "costEb": 1000,
    "notes": "Автоогонь(3),\nАвтоогонь(4)\n\nЭкзотический тяжелый пистолет, который может быть преобразован в экзотический ПП или экзотическую штурмовую винтовку за 1 минуту без проверки, при условии, что у пользователя есть доступ к модульным частям оружия. Все детали прекрасно укладываются в пенопластовый футляр для переноски. Не смотря на то что является Экзотическим оружием - имеет 2 слота опций снаряжения, совместимых только с прицелами.\nИсточник: Черный Хром\n\nПараметры источника: Навык: Автоогонь / Пистолет / Тактическое; Урон: 2d6 / 3d6 / 5d6; Магазин: 25 Винтовка, / 30 С Пистолет, / 8 Т Пистолет; ROF: 1-2; Руки: 12; Можно Скрыть: НЕТ; Цена: 1000eb / (Оч.Дорогое)",
