    "costEb": 5000,
    "notes": "Требуется ТЕЛ 11+\n\nСкорострельный Экзотический Гранатомёт (2 СКА) Магазин вмещает четыре гранаты. Несмотря на то, что это Экзотическое оружие, оно способно стрелять всеми видами гранатных боеприпасов. Для перезарядки требуется 2 Действия, поэтому занимает два Хода. Если оружие не закреплено на станке, то необходимо ТЕЛ 11 или выше, чтобы стрелять из него.\nИсточник: КорБук\n\nПараметры источника: Навык: Ор.кр.калибра; Урон: 6d6; Магазин: 4 Граната; ROF: 2; Руки: 2; Можно Скрыть: НЕТ; Цена: 5000eb / (Роскошь)",
