    "ammoType": "4 Винтовка",
    "concealable": false,
    "costEb": 5000,
    "notes": "Игнорирует ОС ниже 11,\nТребуется ТЕЛ 11+\n\nЭкзотическая Штурмовая Винтовка, из которой нельзя стрелять используя “Автоматический Огонь” и “Прицельный Выстрел”. При стрельбе использует Навык “Оружие Крупного Калибра\"\" вместо навыка \"\"Тактическое Оружие\"\". Магазина хватает на 4 выстрела. Полностью игнорирует броню цели, если она ниже 11 ОС.\nС Бронёй 11 ОС и выше взаимодействует как обычно. Для перезарядки требуется 2 Действия, поэтому занимает два Хода. Если оружие не закреплено на станке, то необходимо ТЕЛ 11 или выше, чтобы стрелять из него.\nИсточник: КорБук\n\nПараметры источника: Навык: Ор.кр.калибра; Урон: 5d6; Магазин: 4 Винтовка; ROF: 1; Руки: 2; Можно Скрыть: НЕТ; Цена: 5000eb / (Роскошь)",
    "quality": "Standard",
