    "ammoType": "4 Ракета",
    "concealable": false,
    "costEb": 500,
    "notes": "Взрывы,\nДвойнойСпуск\n\nЭкзотическая ракетная установка с максимальной дальностью стрельбы 400 м. Ее магазин вмещает 4 бронебойные ракеты. Когда вы атакуете этим оружием, оно выпускает в цель сразу две ракеты. Однако вместо того, чтобы владелец делал проверку навыка владения Оружием Крупного Калибра для попадания в цель, ГМ решает, куда попадут обе ракеты. Уклонение от взрыва, произведенного этим оружием — это проверка навыка Уклонение СЛ15, которую может попытаться выполнить только цель, способная уклоняться от пуль, и в случае успеха она оказывается вне зоны взрыва. При определении места попадания двух ракет, ГМ должен выбрать два места в пределах 50 м от предполагаемой цели, которые должны находиться на расстоянии не менее 10 м друг от друга. Это оружие не может быть улучшено техником с целью убрать эту особенность прицеливания с помощью ГМ.\nИсточник: Гараж Вудчипер\n\nПараметры источника: Навык: Ор.кр.калибра; Урон: 8d6; Магазин: 4 Ракета; ROF: 1; Руки: 2; Можно Скрыть: НЕТ; Цена: 500eb / (Дорогое)",
