    "costEb": 100,
    "notes": "Плохого качества,\nПри 1 самоуничтожается\n\nЭкзотическая ракетная установка низкого качества, способная стрелять только бронебойными ракетами. Каждая установка поставляется с бронебойной ракетой, уже заряженной в магазин. Если во время стрельбы из оружия вы получаете критический провал (1) или пытаетесь извлечь заряженную ракету из магазина Красотки, боеприпасы внутри немедленно детонируют, центр взрыва — оружие.\nЭто полностью уничтожает её (а иногда и пользователя).\nИсточник: Черный Хром\n\nПараметры источника: Навык: Ор.кр.калибра; Урон: 8d6; Магазин: 1 Ракета; ROF: 1; Руки: 2; Можно Скрыть: НЕТ; Цена: 100eb / (Премиум)",
