    "notes": "Экзотическое одноручное Среднее ОББ Отличного качества. Оружие хранится в специальной перчатке. В ход, когда клинок извлечён, и только в этот ход считается Экзотическим одноручным ОТ ОББ отличного качества, СКА 1.\nпока клинок извелчён, рука в перчатке не может использоваться для других целей. Любые опции имплантов этой руки недоступны, пока перчатка надета. Убрать клинок это Действие, снять и надеть перчатку, аналогично требует Действие.\nПока клинок спрятан, перчатка может быть спрятана, например, в длинных рукавах или под одеждой при помощи навыка Скрытие/Раскрытие Объекта. Открытое ношение позволяет легко определить, что это за перчатка.\nИсточник: Черный Хром\n\nПараметры источника: Тип: Среднее; Урон: 2d6 / 4d6; ROF: 1,2; Руки: 1; Можно Скрыть: Особое; Цена: 1000eb(Оч.Дорогое)",
