    "notes": "За дополнительные 10 eb мы даже выгравируем твоё имя на лезвии, чтобы ты мог оставить свой след на плоти врага.\nЭкзотическое Среднее Оружие Ближнего Боя, которое можно скрытно носить. Любой, кого коснётся термокинжал, сильно воспламеняется (СМ. CP:R, СТР. 180).\nИсточник: THE 12 DAYS OF REDMAS\n\nПараметры источника: Тип: Среднее; Урон: 2d6; ROF: 2; Руки: 1; Можно Скрыть: ДА; Цена: 1000eb(Оч.Дорогое)",
