    "ammoType": "—",
    "concealable": false,
    "costEb": 5000,
    "notes": "Экзотическое двуручное ОТ ОББ Отличного качества.\nРаз в минуту (20 раундов) Действием пользователь может покрыть лезвие одной или несколькими жидкостями из контейнера в рукояти. Многократное использование одной и той же жидкости не даёт результата, однако три разных могут комбинировать эффекты, если пользователь того желает. Каждая жидкость действует 1 минуту. Каждый контейнер содержит одну дозу жидкости, и только специальные жидкости Плачущего Разбойника совместимы с этим оружием. В рукояти 3 ёмкости для жидкостей, перезаряжаемых в любой комбинации жидкостей Действием.\nСтоимость одной дозы 100 (Премиум).\nИсточник: Черный Хром\n\nПараметры источника: Тип: О.Тяжелое; Урон: 4d6; ROF: 1; Руки: 2; Можно Скрыть: НЕТ; Цена: 5000eb(Роскошь)",
