    "currentAmmo": 0,
    "ammoType": "—",
    "concealable": false,
    "costEb": 1000,
    "notes": "Экзотическое ОТ ОББ\nТребуется ТЕЛ 11+ для использования. Действием можно запустить нагрев, который длится 1 минуту (20 раундов), в ходе которого клинок надо держать навесу, иначе он вплавит себя в поверхность на которой оставлен, что уничтожит оружие. Для нагрева требуется 3 стандартных батареи стоимостью 50 eb (Дорогое), которые уничтожаются безвозвратно в процессе нагрева. Предохранитель замены батарей можно отомкнуть только на охлаждённом оружии, что требует действия. Будучи раскалённым Тесак начинает вибрировать.\nСледующие 5 минут Тесак имеет урон до 5d6, игнорирует броню ниже 11 ОС, а так же кто-угодно или что-угодно, ударенное Тесаком начинает Слабо Гореть (2).\nЕсли Тесак отпустить или выронить пока он раскалён, он начинает вплавляться в поверхность на которой лежит, уничтожая сам себя. Через 30 секунд батарейный блок начинает дымить. Из-за размером тесака - его нельзя использовать одной рукой никоим образом.\nИсточник: Черный Хром\n\nПараметры источника: Тип: О.Тяжелое; Урон: 4d6; ROF: 1; Руки: 2; Можно Скрыть: НЕТ; Цена: 1000eb(Оч.Дорогое)",
