    "costEb": 5000,
    "notes": "Экзотическое ОТ ОББ отличного качества перманентно установленное в Боевую Перчатку. Может быть извлечено и спрятано без Действия. Когда оружие извлечено, рука не может быть использована для других целей. Боевая перчатка имеет 1 свободный слотом для опций кибер-руки или кибер-конечности. Даёт пользователю +2 к навыку Допроса при явном использовании.\nстоимость установки опции импланта в перчатку аналогична установке в кибер-руку. Любые опции имплантов руки недоступны, пока перчатка надета. Снять и одеть перчатку требует Действие.\nИсточник: Черный Хром\n\nПараметры источника: Тип: О.Тяжелое; Урон: 4d6; ROF: 1; Руки: 1; Можно Скрыть: НЕТ; Цена: 5000eb(Роскошь)",
