    "costEb": 1000,
    "notes": "Когда Кулак Носорога надет на руку и подключен Личным Портом, урон пользователя в Драке 4d6 урона.\nДействием можно трансофрмировать в Экзотическое ОТ ОББ отличного качества и обратно. Когда оружие вскинуто, пользователь не может держать что-либо в этой руке. Любые опции имплантов руки, использующей Кулак Носорога недоступны.\nКулак Носорога можно снять и надеть Действием, частью которого является подключение свободного Личного Порта. Кулак Носорога нельзя скрыть.\nБлагодаря особенностям конструкции обратимо уничтоженный Кулак Носорога может быть восстановлен за 6 часов, в случае успешной проверки Оружейника или автомеханика. При провале на полпути ты понимаешь, что надо начать заново.\nИсточник: Черный Хром\n\nПараметры источника: Тип: О.Тяжелое; Урон: 4d6; ROF: 1; Руки: 1; Можно Скрыть: НЕТ; Цена: 1000eb(Оч.Дорогое)",
