    "concealable": false,
    "costEb": 600,
    "notes": "Классификация: тяжёлый ПП отличного качества\nТаблица дальности: субкомпактный ПП\nОсобые режимы огня: автоогонь (ПП 4), подавляющий огонь\nСвободные слоты: 2\nПриспособления: увеличенный магазин\nОсобые свойства: нет\n\nПистолет-пулемёт с увеличенным магазином, созданный как более крупнокалиберная версия популярного Minami 10 для редких подразделений службы безопасности, где скрытность и маскировка не имеют значения. Внутри корпорации Takanami мгновенно стал хитом, однако за её пределами продажи так и остались слабыми.\n\nПараметры источника: Навык (одиночного выстрела): Короткоствольное оружие; Урон: 3d6; Магазин: 50; ROF: 1; Руки: 1; Можно Скрыть: Нет; Цена: 600eb (Дорого)",
