    "costEb": 3000,
    "notes": "Классификация: пулемёт\nТаблица дальности: марксманская винтовка\nОсобые режимы огня: автоогонь (пулемёт 5), подавляющий огонь\nСвободные слоты: 3\nПриспособления: нет\nОсобые свойства: для стрельбы из этого оружия требуется ТЕЛО 11 или выше, если только оно не установлено на крепление или стрелок не находится в положении лёжа. Кочевник может выбрать это оружие при первичной установке крепления для тяжёлого оружия на транспорт.\n\nНепритязательный. Бескомпромиссный. Беспощадный. Любимое тяжёлое оружие Лидии. Штурмовой Midnight Arms Midnight HB готов пройти с тобой тёмную дорогу до конца. Когда часы бьют полночь доверься звону колокола.\n\nПараметры источника: Навык (одиночного выстрела): Тяжёлое оружие; Урон: 5d6; Магазин: 60; ROF: 1; Руки: 2; Можно Скрыть: Нет; Цена: 3 000eb (Роскошь)",
