    "costEb": 1400,
    "notes": "Классификация: пулемёт\nТаблица дальности: штурмовая винтовка\nОсобые режимы огня: автоогонь (пулемёт 4), подавляющий огонь\nСвободные слоты: 3\nПриспособления: нет\nОсобые свойства: перезарядка этого оружия требует двух действий перезарядки. Для стрельбы из этого оружия требуется ТЕЛО 11 или выше, если только оно не установлено на крепление или стрелок не находится в положении лёжа. Кочевник может выбрать это оружие при первичной установке крепления для тяжёлого оружия на транспорт.\n\nЛёгкий пулемёт Militech, созданный для массового производства и принятия на вооружение современными армиями по всему миру в роли мобильного автоматического оружия отделения. Для многих армий он пришёл на смену устаревшим автоматическим лёгким пулемётам, которые непрерывно служили ещё со времён Четвёртой корпоративной войны.\n\nПараметры источника: Навык (одиночного выстрела): Тяжёлое оружие; Урон: 4d6; Магазин: 80; ROF: 1; Руки: 2; Можно Скрыть: Нет; Цена: 1 400eb (Очень дорого)",
