    "concealable": false,
    "costEb": 100,
    "notes": "Дробь 3d6,\nЖакан 5d6,\nПлохого качества,\nТЕЛ 10+ или травма\n\nЕсть оружие тонкое, оружие элегантное и оружие, способное поражать цели с хирургической точностью. «Carnage» от Бюджет Армс не обладает ни одним из этих качеств. Его дизайнеры следовали одному простому правилу: чем больше, тем лучше. Результат? Карнаж огромен, наносит невероятный урон и имеет отдачу, которая может выбить ваше плечо из сустава.\nДробовик Плохого Качества с Силовым-Улучшением. Магазин рассчитан на 5 патронов. При стрельбе пользователем без ТЕЛА 10 или выше он получает критическую травму «Разорванная мышца», если у него ее еще не было.\n\nПараметры источника: Навык: Тактическое; Урон: 3d6 / 5d6; Магазин: 5 Дробовик; ROF: 1; Руки: 2; Можно Скрыть: НЕТ; Цена: 100eb / (Премиум)",
