    "ammoType": "32 Дробовик",
    "concealable": false,
    "costEb": 1000,
    "notes": "Дробь 4к6\n\nДробовики не отличаются изяществом: хотя они, несомненно, мощны, они часто страдают от неуклюжести и неточности. Исключая L-69 Zhuo от Кан Тао. Как и другое оружие, производимое китайской корпорацией, L-69 Zhuo оснащен новейшей электроникой. Сверхчувствительный радар сканирует местность за вас, самостоятельно определяя цели. Каждый из восьми подствольных магазинов всегда готов и ждет, чтобы кого-нибудь растерзать.\nЭкзотический дробовик со Смарт-Улучшением. Магазин вмещает 32 патрона и может быть заряжен только Улучшенными Умными патронами для Смарт-дробовика. При стрельбе из этого оружия за каждую проверку атаки расходуется 8 патронов. Без восьми заряженных снарядов оружие не будет стрелять в целях безопасности. Из-за огромного количества боеприпасов, расходуемых на выстрел, L-69 Zhuo наносит урон 4d6 вместо типичного для дроби урона 3d6.\n\nПараметры источника: Навык: Тактическое; Урон: 4d6; Магазин: 32 Дробовик; ROF: 1; Руки: 2; Можно Скрыть: НЕТ; Цена: 1000eb / (Оч.Дорогое)",
