    "costEb": 500,
    "notes": "Омаха выглядит как классический ствол, но не позволяйте внешности обмануть вас. Этот драгоценный камень от Militech скрывает в себе мощную систему электромагнитных рельс. Неудивительно, что это огнестрельное оружие часто можно найти в кобурах корпоратов, находящихся на верху пищевой цепи. Благодаря небольшому размеру он удобно помещается в портфеле или в бардачке корпоративного лимузина.\nЭкзотический тяжелый пистолет с Техно-Улучшением. Он имеет магазин на 9 выстрелов. Когда он заряжен с помощью Техно-Улучшения, он остается таковым до конца хода, в котором из него стреляли. Кроме того, во время зарядки Омаха сохраняет СКА 2 и тратит до 3 патронов вместо 1 на каждую проверку атаки. Если в состоянии «Заряжено» в магазине меньше 3 патронов, магазин опустошается с выстрелом.\n\nПараметры источника: Навык: Пистолет; Урон: 3d6; Магазин: 9 Т Пистолет; ROF: 2; Руки: 1; Можно Скрыть: ДА; Цена: 500eb / (Дорогое)",
