    "costEb": 1000,
    "notes": "Буря уродлива, неудобна и небезопасна, но чертовски эффективна. Этот Нео-Советский электромагнитный пистолет не нуждается в зарядке, чтобы пробивать стены, плотностью практически равной плотности нейтронной звезды. Чтобы нажать на курок, не сломав руку, рекомендуется использовать продвинутые мышечные киберимпланты.\nЭкзотический очень тяжелый пистолет с Техно-Улучшением. Магазин рассчитан на 4 выстрела. Его Тех-Улучшение можно зарядить без действия Движения. Пользователь без киберимплантов «Усиленные Мышцы и Кости» или «Киберрука», стреляющий из РТ-46 «Буря», получает критическую травму «Сломанная рука», если у него ее еще не было.\n\nПараметры источника: Навык: Пистолет; Урон: 4d6; Магазин: 4 ОТ Пистолет; ROF: 1; Руки: 1; Можно Скрыть: НЕТ; Цена: 1000eb / (Оч.Дорогое)",
