    "concealable": false,
    "costEb": 500,
    "notes": "Любой боеприпас\n\nКогда миру потребовалось новое поколение снайперских винтовок, способных пробивать все более и более тяжелую броню, первым ответом стал советский СПТ32 «Град», который многие считали самой мощной снайперской винтовкой на рынке. Возможно, он не обладает такой же тщательностью к деталям, как его коллеги из Арасаки или Милитеха, но в руках хорошо обученного снайпера, который не полагается на ветровые корректировки подсчитываемые самим оружием, «Град» представляет собой поистине разрушительную силу.\nЭкзотическая снайперская винтовка Отличного Качества с Техно-Улучшением. Несмотря на то, что это Экзотическое оружие, оно все равно может заряжать необычные боеприпасы. После выстрела ему требуется Действие, чтобы передёрнуть затвор, прежде чем из него можно будет выстрелить снова.\n\nПараметры источника: Навык: Тактическое; Урон: 5d6; Магазин: 4 Винтовка; ROF: 1; Руки: 2; Можно Скрыть: НЕТ; Цена: 500eb / (Дорогое)",
