    "notes": "Некомата — требовательное оружие. Он требует ухода, регулярного обслуживания и времени, чтобы научиться им лучше всего пользоваться. Но оно того стоит. Действительно, действительно того стоит. Эта электромагнитная снайперская винтовка — технологическое чудо. Наемникам, не состоящим на службе в правительстве или крупной мегакорпорации, практически невозможно заполучить его… почти.\nСнайперская винтовка с Техно-Улучшением. Пока Заряжена с помощью Техно-Улучшения, его пользователь может видеть простые очертания цели и вести огонь как через тонкое, так и через толстое укрытие.\n\nПараметры источника: Навык: Тактическое; Урон: 5d6; Магазин: 4 Винтовка; ROF: 1; Руки: 2; Можно Скрыть: НЕТ; Цена: 1000eb / (Оч.Дорогое)",
